\label{lyuseippav}
Let $(t_n)_n \subset \mathbb{R}$, where $t_n \neq 0$ when $n \neq 0$, be a sequence such that the family of functions $(\mathrm{sinc} \pi(\cdot -t_n))_n$ is a Riesz basis for $PW_{[-\pi,\pi]}$, then the function
\begin{equation}
S(z) = \lim_{r \rightarrow \infty} (z-t_0) \prod_{\{ t_n \ : \ |t_n|<r, n \neq 0 \}} \Big(1-\frac{z}{t_n}  \Big)\nonumber
\end{equation}
is entire, where convergence is uniform on compacta,  and the biorthogonal functions $(G_n)_n$ of $$(\mathrm{sinc} \pi((\cdot) -t_n))_n$$ are given by
\begin{equation}
G_n(z) = \frac{S(z)}{(z-t_n)S'(t_n)}.\nonumber
\end{equation}

Let $A:\ell_2(\mathbb{N}) \rightarrow \ell_2(\mathbb{N})$ be an onto isomorphism. Regard $A$ as a matrix map with respect to the unit vector basis of $\ell_2(\mathbb{N})$.  Let $\pi_k$ be the orthogonal projection onto the span of the first $k$ terms of the unit vector basis.  If 
\begin{equation}\label{matunif}
\sup_{j \in \mathbb{N}} \| (\pi_{k_j} A \pi_{k_j})^{-1}\|< \infty,
\end{equation}
for an increasing sequence $(k_j)_{j \in \mathbb{N}},$ then $A$ is said to be uniformly invertible as a matrix map with respect to the projections $(\pi_{k_j})_{j \in \mathbb{N}}$.  The terms in inequality (\ref{matunif}) should be interpreted as standard matrix norms and inverses of finite dimensional matrices.

\noindent 1) $\Longrightarrow$ 2): By Lemma \ref{firstone}, we only need to show that that $$\sup_{\ell \in \mathbb{N}} \|L_\ell^{-1} \| < \infty.$$  This follows from the identity\\
\begin{equation}\label{ident}
L_\ell^{-1} = [I-(I-P_\ell)L](P_\ell L P_\ell)^{-1}+I-P_\ell,
\end{equation}
which is hereby demonstrated:
\begin{eqnarray}
[I-(I-P_\ell)L](P_\ell L P_\ell)^{-1}+I-P_\ell & = & [I-(I-P_\ell)L]P_\ell L_\ell^{-1} P_\ell+I-P_\ell\\
& = & P_\ell L_\ell^{-1} P_\ell -L P_\ell L_\ell^{-1} P_\ell+I\nonumber\\
& = & (I-L)P_\ell L_\ell^{-1} P_\ell +I.\nonumber
\end{eqnarray}
We have $(I-L)P_\ell = I -L_\ell$, so
\begin{eqnarray}
[I-(I-P_\ell)L](P_\ell L P_\ell)^{-1}+I-P_\ell & = & (I-L) L_\ell^{-1} P_\ell +I\\
& = & L_\ell^{-1}P_\ell -P_\ell +I.\nonumber
\end{eqnarray}
Noting that $L_\ell (I-P_\ell) = I-P_\ell$, we obtain $L_\ell^{-1}P_\ell -P_\ell +I = L_\ell^{-1}$, which proves the identity.\\

\noindent 2) $\Longrightarrow$ 1): Noting that $(P_\ell L P_\ell)^{-1} = P_\ell L_\ell^{-1} P_\ell$ yields the result.\\

Suppose that the sequence $(f_n)_{n \in \mathbb{Z}^d}$ is a Riesz basis for $L_2([-\pi,\pi]^d)$.  We compute the biorthogonal functions of $(f_{\ell,n})_{n \in \mathbb{Z}^d}$ when $n \in C_{\ell,d}$:
\begin{eqnarray}
f_{\ell,n}^*  & = & \sum_{k \in \mathbb{Z}^d} \langle f_{\ell,n}^* , e_k \rangle e_k = \sum_{k \in C_{\ell,d}} \langle f_{\ell,n}^* , e_k \rangle e_k + \sum_{k \notin C_{\ell,d}}  \langle f_{\ell,n}^* , e_k \rangle e_k\nonumber\\
& = & \sum_{k \in C_{\ell,d}} \langle f_{\ell,n}^* , e_k \rangle e_k.\nonumber
\end{eqnarray}
Passing to the Fourier transform and defining $G_{\ell, n} = \mathcal{F}(f_{\ell,n}^*)$, we have
\begin{eqnarray}\label{firstsum}
G_{\ell,n}(t) & = & \sum_{k \in C_{\ell,d}} G_{\ell,n}(k)\mathrm{SINC}\pi(t-k)\\
& = & \bigg( \sum_{k \in C_{\ell,d}}\frac{G_{\ell,n}(k)(-1)^{k(1)+\ldots+k(d)} t(1)\cdot\ldots\cdot t(d)}{(t(1)-k(1))\cdot \ldots\cdot(t(d)-k(d))} \bigg)\mathrm{SINC}(\pi t), \quad t \in \mathbb{R}^d.\nonumber
\end{eqnarray}
Denote the $k^{th}$ summand in equation (\ref{firstsum}) by $A_k$, then
\begin{eqnarray}
A_{\ell,n,k}\!\! & = &\!\! A_{\ell,n,k} \frac{\prod_{j_1 = -\ell \atop j_1 \neq k(1)}^\ell (t(1)-j_1) \cdot \ldots \cdot \prod_{j_d = -\ell \atop j_d \neq k(d)}^\ell (t(d)-j_d)}{\prod_{j_1 = -\ell \atop j_1 \neq k(1)}^\ell (t(1)-j_1) \cdot \ldots \cdot \prod_{j_d = -\ell \atop j_d \neq k(d)}^\ell (t(d)-j_d)}\nonumber\\
& = &\!\! \frac{G_{\ell,n}(k)(-1)^{k(1)+\ldots+k(d)}t(1)\cdot\ldots\cdot t(d) \prod_{j_1 = -\ell \atop j_1 \neq k(1)}^\ell (t(1)-j_1) \cdot \ldots \cdot \prod_{j_d = -\ell \atop j_d \neq k(d)}^\ell (t(d)-j_d)}{\prod_{j_1 = -\ell}^\ell (t(1)-j_1) \cdot \ldots \cdot \prod_{j_d = -\ell}^\ell (t(d)-j_d)}\nonumber\\
& = &\!\! \frac{G_{\ell,n}(k)\frac{1}{(\ell!)^2}(-1)^{k(1)+\ldots+k(d) +\ell d}\prod_{j_1 = -\ell \atop j_1 \neq k(1)}^\ell (t(1)-j_1) \cdot \ldots \cdot \prod_{j_d = -\ell \atop j_d \neq k(d)}^\ell (t(d)-j_d)}{\prod_{j_1 = 1}^\ell \Big(1-\frac{t(1)^2}{j_1^2}\Big) \cdot \ldots \cdot \prod_{j_d = 1}^\ell \Big(1-\frac{t(d)^2}{k_d^2}\Big)}\nonumber\\
& = &\!\! \frac{p_{\ell,n,k} (t)}{Q_{d,\ell} (t)},\nonumber
\end{eqnarray}
where $p_{\ell,n,k}$ is some polynomial with coordinate degree at most $2\ell$. Substituting into equation ({\ref{firstsum}}), we obtain
$$G_{\ell,n}(t) = \Big(\sum_{k \in C_{\ell,d}} p_{\ell,n,k}(t) \Big)\frac{\mathrm{SINC}(\pi t)}{Q_{d,\ell} (t)}:= \phi_{\ell,n} (t)\frac{\mathrm{SINC}(\pi t)}{Q_{d,\ell} (t)},$$ where $\phi_{\ell,n}$ is a polynomial having coordinate degree at most $2 \ell$.  The fact that each zero of $\mathrm{sinc}(\pi z)$ has multiplicity one implies that the zero set of $\frac{\mathrm{SINC}(\pi t)}{Q_{d,\ell} (t)}$ (which is entire) is $(\mathbb{Z}\setminus \{-\ell,\cdots, \ell\})^d \subset \mathbb{C}$. Using that $\mathrm{SINC}\pi(x-y)$ is the reproducing kernel for $PW_{[-\pi,\pi]^d}$, we see that  $$G_{\ell,n}(t_m) = \delta_{nm},$$ for all $n,m \in C_{\ell,d}$. This yields that $$1 = \phi_{\ell,n} (t_n)\Big(\frac{\mathrm{SINC}(\pi t)}{Q_{d,\ell} (t)}\Big)\Big|_{t_n}.$$ This shows $\phi_{\ell,n} (t_n) \neq 0$ and $\frac{\mathrm{SINC}(\pi t_n)}{Q_{d,\ell} (t_n)}\neq0$ for $n \in C_{\ell,d}$, and that $t_n \notin (\mathbb{Z}\setminus \{-\ell,\cdots, \ell\})^d$ (statement 1) of Lemma \ref{othermain}).\\

\noindent For $n,m \in C_{\ell,d}, n\neq m, $ $$0 = G_{\ell,n}(t_m) = \phi_{\ell,n} (t_m)\Big(\frac{\mathrm{SINC}(\pi t)}{Q_{d,\ell} (t)}\Big)\Big|_{t_m},$$ We conclude that 
\begin{displaymath}
   \phi_{\ell,n}(t_m) = \left\{
     \begin{array}{lr}
       \frac{Q_{d,\ell}(t_n)}{\mathrm{SINC}\pi t_n} \neq 0,  &  n = m\\
       0, & n \neq m
     \end{array}
   \right.
\end{displaymath}
for $n,m \in C_{\ell,d}$ From this, the ``existence'' part of statement 2) in Lemma \ref{othermain} readily follows.  Restated, the evaluation map taking the space of all polynomials of coordinate degree at most $2 \ell$ to $\mathbb{R}^{(2\ell+1)^d}$ is onto.  These spaces have the same dimension, hence the evaluation map is a bijection, which completes the proof of statement 2).\\

\noindent Suppose that 1) and 2) hold.  For $n \in C_{\ell,d}$, let $p_{\ell,n}$ be the unique polynomial of coordinate degree at most $2\ell$ such that $p_{\ell,n} (t_m) = \delta_{nm}$ for $m \in C_{\ell,d}$.  Define 
\begin{equation}\label{biorth}
\Phi_{\ell,n} (t) = \frac{Q_{d,\ell} (t_n) \mathrm{SINC}\pi t}{Q_{d,\ell}(t) \mathrm{SINC}\pi t_n}p_{\ell,n}(t).
\end{equation}
Partial fraction decomposition can be used to show that $\Phi_{\ell,n} \in PW_{[-\pi,\pi]^d}$.  For $n,m \in C_{\ell,d}$, we therefore have $$\delta_{n,m} = \langle \Phi_{\ell,n} (\cdot) , \mathrm{SINC}\pi((\cdot)-t_m) \rangle = \langle \mathcal{F}^{-1}(\Phi_{\ell,n}) , f_m \rangle.$$
Let $L_\ell$ be defined as before.  Let $f=\sum_{n \in \mathbb{Z}^d} c_n e_n$ such that $L_\ell (f) = 0$, then $$0 = \sum_{n \in C_{\ell,d}} c_n f_n+\sum_{n \notin C_{\ell,d}}c_n e_n.$$  If, for each $n \in C_{\ell,d}$ we integrate the above equation against $\mathcal{F}^{-1}(\Phi_{\ell,n})$, we see that $c_k = 0$ for $k \in C_{\ell,d}$, so that $c_k =0$ for all $k \in \mathbb{Z}^d$.  $L_\ell$ is one to one, so by Lemma \ref{secondone}, it is an onto isomorphism from $L_2([-\pi,\pi]^d)$ to itself.

\noindent It is clear that 1) implies 2). For the other direction, note that the equality $L_\ell^* = P_\ell L^* +I - P_\ell$ implies that
\begin{equation}\label{prebiorthapprox}
I = (L_\ell^*)^{-1} P_\ell L^* +(L_\ell^*)^{-1}(I-P_\ell).
\end{equation}
This implies that $(L_\ell^*)^{-1}P_\ell$ is pointwise bounded.  Together with the assumption in 2), this implies $(L_\ell^*)^{-1}$ is pointwise bounded, hence norm bounded by the uniform boundedness principle.  This yields uniform invertibility of $L$.

\label{blip}
\noindent The following are equivalent:\\

\noindent 1) For all $g \in L_2([-\pi,\pi]^d)$, we have
\begin{equation}\label{biorthapprox}
g = \lim_{\ell \rightarrow \infty} (L_\ell^*)^{-1} P_\ell L^* g.
\end{equation}
\noindent 2) $L$ is uniformly invertible.

\label{blip2}
Statement (c) of Theorem \ref{maintheorem} is true iff
\begin{eqnarray}\label{equivlimit}
0 = \lim_{\ell \rightarrow \infty} \sum_{n \in C_{\ell,d}} |f(t_n)|^2\bigg[1- \frac{\mathrm{SINC} \pi t_n}{Q_{d,\ell} (t_n)} \bigg]^2:=  \lim_{\ell \rightarrow \infty} S_{\ell,d}, \quad f\in PW_{[-\pi,\pi]^d}.
\end{eqnarray}

\noindent Note that $Le_n = f_n$ implies that $f_n^* = (L^*)^{-1}e_n.$  Similarly, $f_{\ell,n}^* = (L_\ell^*)^{-1}e_n$.  Given $f \in PW_{[-\pi,\pi]^d}$, let $g= \mathcal{F}^{-1}(f)$.  Equation (\ref{biorthapprox}) shows:
\begin{eqnarray}
\mathcal{F}^{-1}(f) & = & \lim_{\ell \rightarrow \infty} (L_\ell^*)^{-1} \sum_{n \in C_{\ell,d}} \langle L^* g, e_n \rangle e_n = \lim_{\ell \rightarrow \infty} (L_\ell^*)^{-1} \sum_{n \in C_{\ell,d}} \langle g, f_n \rangle e_n\nonumber\\
& = & \lim_{\ell \rightarrow \infty} \sum_{n \in C_{\ell,d}} \langle g, f_n \rangle f_{\ell,n}^* = \lim_{\ell \rightarrow \infty} \sum_{n \in C_{\ell,d}} f(t_n) f_{\ell,n}^*.\nonumber
\end{eqnarray}
Passing to the Fourier transform, we have
\begin{equation}\label{blah}
f = \lim_{\ell \rightarrow \infty} \sum_{n \in C_{\ell,d}} f(t_n) \mathcal{F}(f_{\ell,n}^*), \quad f \in PW_{[-\pi,\pi]^d},
\end{equation}
where convergence in both $L_2$ and uniform.  The values of a function in $PW_{[-\pi,\pi]^d}$ on the set $(t_n)_{n \in \mathbb{Z}^d}$ uniquely determine the function.  This and equation (\ref{biorth}) show that $$\mathcal{F}(f_{\ell,n}^*)(t) = G_{\ell,n}(t) = \frac{Q_{d,\ell} (t_n) \mathrm{SINC}\pi t}{Q_{d,\ell}(t) \mathrm{SINC}\pi t_n}p_{\ell,n}(t), \quad n \in C_{\ell,d}.$$                               




This implies that
\begin{eqnarray}
\Psi_\ell(t) \frac{\mathrm{SINC} (\pi t)}{Q_{d,\ell} (t)} & = & \Big(\sum_{n \in C_{\ell,d}} f(t_n) p_{\ell,n}(t)\Big)  \frac{\mathrm{SINC} (\pi t)}{Q_{d,\ell} (t)}\nonumber\\
& = & \sum_{n \in C_{\ell,d}} f(t_n) \frac{\mathrm{SINC} \pi t_n}{Q_{d,\ell} (t_n)}\mathcal{F}(f_{\ell,n}^*)(t).\nonumber
\end{eqnarray}
Combined with equation (\ref{blah}), we see that statement (c) of Theorem \ref{maintheorem} holds iff
\begin{eqnarray}
0  =  \lim_{\ell \rightarrow \infty} \sum_{n \in C_{\ell,d}} f(t_n)\bigg[1- \frac{\mathrm{SINC} \pi t_n}{Q_{d,\ell} (t_n)} \bigg] \mathcal{F}(f_{\ell,n}^*),  \quad f\in PW_{[-\pi,\pi]^d},\nonumber
\end{eqnarray}
where the limit is in the $L_2$ sense. Passing to the inverse Fourier transform, statement (c) holds iff
\begin{eqnarray}\label{blip3}
0 = \lim_{\ell \rightarrow \infty} (L_\ell^*)^{-1}\bigg( \sum_{n \in C_{\ell,d}} f(t_n)\bigg[1- \frac{\mathrm{SINC} \pi t_n}{Q_{d,\ell} (t_n)} \bigg] e_n \bigg), \quad f\in PW_{[-\pi,\pi]^d}.
\end{eqnarray}
In addition to having uniformly norm bounded inverses, $L_\ell$ is pointwise bounded, so there exists $m, M>0$ such that for all $\ell \in \mathbb{N}$, $f \in PW_{[-\pi,\pi]^d}$, $m\| f\| \leq \|(L_\ell^*)^{-1} f \| \leq M\| f \|$.  This, combined with equation (\ref{blip3}), proves the proposition.

\label{sinclimitstuff}
\noindent The following are true:\\

\noindent 1) $\sup_{x \in \mathbb{R}} \sup_{\ell \in \mathbb{N}} \Big|\frac{\mathrm{sinc}(\pi x)}{Q_{1,\ell}(x)} \Big|=1.$\\

\noindent 2) Define $\Delta_{\ell,d} = \Big\{ n \in \mathbb{Z}^d \big| \Big\| \frac{t_n}{\ell+1} \Big\|_{\infty} < \frac{1}{\ell^{2/3}} \Big\}$ for $\ell \in \mathbb{N}$, then
\begin{eqnarray}
0 \leq 1-\frac{\mathrm{SINC}(\pi t_n)}{Q_{d,\ell} (t_n)} < 1-e^{\frac{-d(\ell+2)}{\ell^{4/3}-1}}, \quad n \in \Delta_{\ell,d}.
\end{eqnarray}

\noindent For 1), the identity $$\mathrm{sinc}(\pi t) = \prod_{k=1}^\infty \Big( 1-\frac{t^2}{k^2} \Big)$$ implies
\begin{equation}
\frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell} (t)} = \prod_{k=\ell+1}^\infty \Big(1-\frac{t^2}{k^2} \Big),
\end{equation}
where convergence is uniform on compact subsets of $\mathbb{C}$.  Fix $\ell \in \mathbb{N}$.  If $t \in [0,\ell+1]$, then $\Big|\frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell}(t)} \Big| \leq1.$  Note that $|Q_{1,\ell} (t)| = \prod_{k=1}^\ell \Big(\frac{t^2}{k^2} -1 \Big)$ is increasing on $(\ell+1, \infty)$.  If $t \in (\ell+1, \infty)$, then
\begin{equation}
\Big|\frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell}(t)} \Big| = \Big|\frac{\sin(\pi t)}{\pi t Q_{1,\ell}(t)} \Big| < \frac{1}{\pi(\ell+1)| Q_{1,\ell} (\ell+1)|}.\nonumber
\end{equation}
Computation yields
\begin{equation}
| Q_{1,\ell} (\ell+1)| = \frac{(2\ell+1)!}{\ell! (\ell+1)!},\nonumber
\end{equation}
so $$ \Big|\frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell}(t)} \Big| < \frac{(\ell!)^2}{\pi(2\ell+1)!} <1 .$$
Observing that $\frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell}(t)}$ is even proves 1).\\

\noindent For 2), let $t \in \mathbb{R}$ such that $\Big| \frac{t}{\ell+1} \Big| < \frac{1}{\ell^{2/3}}$, then $0 < \frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell}(t)}$, and
\begin{eqnarray}\label{logstuff}
-\log\Big( \frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell}(t)} \Big) &  = & -\sum_{k= \ell+1}^\infty \log\Big(1- \frac{t^2}{k^2} \Big) = \sum_{k= \ell+1}^\infty \sum_{j=1}^\infty \frac{t^2}{j k^{2j}}\\
& = & \sum_{j=1}^\infty \frac{1}{j} \Big(\sum_{k= \ell+1}^\infty \frac{1}{k^{2j}} \Big) t^{2j}.\nonumber
\end{eqnarray}
Basic calculus shows that $$\sum_{k= \ell+1}^\infty \frac{1}{k^{2j}} <\frac{1}{(\ell+1)^{2j}}+\frac{1}{(2j-1)(\ell+1)^{2j-1}}.$$  Equality (\ref{logstuff}) implies
\begin{eqnarray}\label{morelogstuff}
-\log\Big( \frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell}(t)} \Big) & < &\sum_{j=1}^\infty \frac{1}{j}\Big(\frac{t}{\ell+1}\Big)^{2j}+  (\ell+1)\sum_{j=1}^\infty \frac{1}{j(2j-1)}\Big(\frac{t}{\ell+1}\Big)^{2j}\\
& < & (\ell+2)\sum_{j=1}^\infty \Big(\frac{t}{\ell+1}\Big)^{2j} < \frac{\ell+2}{\ell^{4/3}-1}.\nonumber
\end{eqnarray}
If $n \in \Delta_{\ell,d}$, then for each $1 \leq k \leq d$, $\Big| \frac{t_n (k)}{\ell+1} \Big| >\frac{\ell+2}{\ell^{4/3}-1}$, so that
\begin{equation}
\log \Big(\frac{\mathrm{SINC}(\pi t_n)}{Q_{d,\ell}(t_n)} \Big)  = \sum_{k=1}^d \log \Big( \frac{\mathrm{sinc}(\pi t_n(k))}{Q_{1,\ell}(t_n(k))} \Big) > -\frac{d(\ell+2)}{\ell^{4/3}-1}.\nonumber
\end{equation}
Statement 2) of Proposition \ref{sinclimitstuff} follows readily.

Proposition \ref{sinclimitstuff} gives the following:\\
\begin{eqnarray}
S_{\ell,d} & \leq & \Big(\sum_{n \in \Delta_{\ell,d}} + \sum_{n \in \mathbb{Z}^d \setminus\Delta_{\ell,d}}\Big) |f(t_n)|^2\bigg[1- \frac{\mathrm{SINC} \pi t_n}{Q_{d,\ell} (t_n)} \bigg]^2 \nonumber\\
& \leq &  \bigg( 1-e^{\frac{-d(\ell+2)}{\ell^{4/3}-1}} \bigg)^2 \sum_{n \in \mathbb{Z}^d} |f(t_n)|^2 + \sum_{n:\ \frac{\ell+1}{\ell^{2/3}}\leq \| t_n \|_\infty} 4 | f(t_n) |^2.
\end{eqnarray}
Now $(f(t_n))_{n \in \mathbb{Z}^d} \in \ell_2(\mathbb{Z}^d)$ implies that $\lim_{\ell \rightarrow \infty} S_{\ell,d} =0$, so that by Proposition \ref{blip2}, statement (c) in Theorem \ref{maintheorem} is true.

\label{simplethm}
Let $(t_n)_{\mathbb{Z}^d} \subset \mathbb{R}^d$ be a sequence such that the associated exponential functions are a uniformly invertible Riesz basis for $L_2([-\pi,\pi]^d)$.  For $N \in \{0,1,2,\ldots \}$, $A>0$, let $E_{\ell,N,A} = [-A (\ell+1/2)^\frac{2N+1}{2N+2},A (\ell+1/2)^\frac{2N+1}{2N+2}]$.  Let $f \in PW_{[-\pi,\pi]^d}$ where $(\Psi_\ell)_\ell$ is the sequence of interpolating polynomials from Theorem \ref{maintheorem}, and let $N \geq 0$.  Let $f \in PW_{[-\pi,\pi]^d}$, and define $$I_{f,\ell} (t) = \Psi_\ell(t) e^{-\sum_{k=1}^{N} \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}},$$ then
\begin{equation}\label{simplecor2}
\lim_{\ell \rightarrow \infty} \Big\| f(t) - I_{f,\ell}(t) \Big\|_{L_2((E_{\ell,N,A})^d)}=0,
\end{equation}
and
\begin{equation}\label{simplecor1}
\lim_{\ell \rightarrow \infty} \Big\| f(t) - I_{f,\ell} (t) \Big\|_{L_\infty((E_{\ell,N,A})^d)}=0.
\end{equation}

\label{simplecormod}
For all $f \in PW_{[-\pi,\pi]^d}$, we have
\begin{equation}                      
\lim_{\ell \rightarrow \infty} \Big\| f(t) - \Psi_\ell(t)\Big\|_{L_2([-A(\ell+1/2)^{1/2},A(\ell+1/2)^{1/2}]^d)}=0,
\end{equation}
and
\begin{equation}\label{simplecor1mod}
\lim_{\ell \rightarrow \infty} \Big\| f(t) - \Psi_\ell(t)\Big\|_{L_\infty([-A(\ell+1/2)^{1/2},A(\ell+1/2)^{1/2}]^d)}=0.
\end{equation}

\label{techlem1}
Let $d \in \mathbb{N}$, $N \in \{0,1,2,\ldots \}$, and $A > 0$.  There exists $M >0$ such that for sufficiently large $\ell$, and any $t \in (E_{\ell,N,A})^d$, we have
\begin{eqnarray}
& &\Big|Q_{d,\ell}(t)  e^{-\sum_{k=1}^{N} \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} - e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)} \mathrm{SINC}(\pi t)\Big|\nonumber\\
& &\quad\leq M(\ell+1/2)^{-\frac{1}{N+1}}|\mathrm{SINC}(\pi t)|.\nonumber
\end{eqnarray}

\label{techlem2}
For all $f \in PW_{[-\pi,\pi]^d}$ and $N \in \{0,1,2,\ldots \}$, we have
\begin{equation}
\lim_{\ell \rightarrow \infty} \sup_{t \in (E_{\ell,N,A})^d} \Big| \Big(e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}  -1 \Big)f(t) \Big| = 0.\nonumber
\end{equation}

\label{blip5}
If $f:(0,\infty) \rightarrow (0,\infty)$ is convex, decreasing, differentiable, and integrable away from $0$, then
$$\frac{1}{4}f'(\ell+1/2)\leq \sum_{k=\ell+1}^\infty f(k) -\int_{\ell+1/2}^\infty f(x) dx \leq 0.$$

Letting $|t| < \ell+1/2$ and recalling equation (\ref{logstuff}), we see that
\begin{eqnarray}\label{blork2}
& &-\log\Big(\frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell} (t)}\Big)-\sum_{k=1}^{\infty} \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}\\
& & \quad = \sum_{k=1}^\infty \Big[ \sum_{j=\ell+1}^\infty \frac{1}{j^{2k}} -\frac{1}{(2k-1)(\ell+1/2)^{2k-1}} \Big] \frac{t^{2k}}{k}.\nonumber
\end{eqnarray}
Applying Proposition \ref{blip5} to the function $f(t) = \frac{1}{t^{2k}}$ when $k \geq 1$, we obtain
\begin{equation}
\frac{-k}{2(\ell+1/2)^{2k+1}} \leq  \sum_{j=\ell+1}^\infty \frac{1}{j^{2k}} -\frac{1}{(2k-1)(\ell+1/2)^{2k-1}} \leq 0.\nonumber
\end{equation}
Equation (\ref{blork2}) becomes
\begin{eqnarray}
\frac{-1}{2(\ell+1/2)}\sum_{k=1}^{\infty} \Big(\frac{t}{\ell+1/2}\Big)^{2k} \leq -\log\Big(\frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell} (t)}\Big)-\sum_{k=1}^{\infty} \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}} \leq 0.\nonumber
\end{eqnarray}
Restated,
\begin{eqnarray}
& &-\frac{1}{2(\ell+1/2)}\frac{\Big( \frac{t}{\ell+1/2} \Big)^2}{1-\Big(\frac{t}{\ell+1/2} \Big)^2}+\sum_{k=N+1}^\infty \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}\\
& &\quad\leq -\log\Big(\frac{\mathrm{sinc}(\pi t)}{Q_{1,\ell} (t)}\Big)-\sum_{k=1}^{N} \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}\nonumber\\
& &\quad\leq  \sum_{k=N+1}^\infty \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}.\nonumber
\end{eqnarray}
Exponentiating,
\begin{eqnarray}\label{blork3}
& & e^{\bigg(-\frac{1}{2(\ell+1/2)}\frac{\big( \frac{t}{\ell+1/2} \big)^2}{1-\big(\frac{t}{\ell+1/2} \big)^2}\bigg)} e^{\sum_{k=N+1}^\infty \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}}\\
& &\quad \leq\frac{Q_{1,\ell} (t)e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}}}{\mathrm{sinc}(\pi t)} \leq  e^{\sum_{k=N+1}^\infty \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}}.\nonumber
\end{eqnarray}
Let $\ell$ be chosen large enough so that $A (\ell+1/2)^\frac{2N+1}{2N+2} <\ell+1/2$. If $\ell$ is large enough, then for any $t \in E_{\ell N,A}$, $t=c (\ell+1/2)^\frac{2N+1}{2N+2}$ for some $c \in [-A,A]$.  For such $t$, inequality (\ref{blork3}) implies
\begin{eqnarray}
& & e^{\bigg(-\frac{1}{2(\ell+1/2)^\frac{N+2}{N+1}}\frac{c^2}{1-c^2(\ell+1/2))^\frac{-1}{N+1}}\bigg)} e^{\sum_{k=N+1}^\infty \frac{c^{2k}}{k(2k-1)}(\ell+1/2)^{\big(1-\frac{k}{N+1}\big)}}\nonumber\\
& & \quad\leq \frac{Q_{1,\ell} (t)e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}}}{\mathrm{sinc}(\pi t)} \leq  e^{\sum_{k=N+1}^\infty \frac{c^{2k}}{k(2k-1)}(\ell+1/2)^{\big(1-\frac{k}{N+1}\big)}}.\nonumber
\end{eqnarray}
If $t \in (E_{\ell,N,A})^d$, then $t=c (\ell+1/2)^\frac{2N+1}{2N+2}$ for some $c \in [-A,A]^d$.  For any such $t$, we have
\begin{eqnarray}\label{blork4}
& & e^{\bigg(-\frac{d}{2(\ell+1/2)^\frac{N+2}{N+1}}\frac{A^2}{1-A^2(\ell+1/2))^\frac{-1}{N+1}}\bigg)} e^{\sum_{k=N+1}^\infty \frac{\|c\|_{2k}^{2k}}{k(2k-1)}(\ell+1/2)^{\big(1-\frac{k}{N+1}\big)}}\\
& & \quad\leq\frac{Q_{d,\ell} (t)e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}}}{\mathrm{SINC}(\pi t)} \leq  e^{\sum_{k=N+1}^\infty \frac{\|c\|_{2k}^{2k}}{k(2k-1)}(\ell+1/2)^{\big(1-\frac{k}{N+1}\big)}}.\nonumber
\end{eqnarray}
On one hand,
\begin{eqnarray}\label{upperinequall}
e^{\sum_{k=N+1}^\infty \frac{\|c\|_{2k}^{2k}}{k(2k-1)}(\ell+1/2)^{\big(1-\frac{k}{N+1}\big)}} \leq e^{\Big( \frac{\|c\|_{2(N+1)}^{2(N+1)}}{(N+1)(2N+1)} + O\big( (\ell+1/2)^\frac{-1}{N+1} \big) \Big)}
\end{eqnarray}
where the ``big O'' constant is independent of $c \in [-A,A]^d$.
\noindent On the other hand,
\begin{eqnarray}\label{lowerinequal}
e^{\frac{\|c\|_{2(N+1)}^{2(N+1)}}{(N+1)(2N+1)}} \leq e^{\sum_{k=N+1}^\infty \frac{\|c\|_{2k}^{2k}}{k(2k-1)}(\ell+1/2)^{\big(1-\frac{k}{N+1}\big)}}.
\end{eqnarray}
Inequality (\ref{blork4}) yields
\begin{eqnarray}\label{blork5}
& & \bigg(e^{-\frac{d}{2(\ell+1/2)^\frac{N+2}{N+1}}\frac{A^2}{1-A^2(\ell+1/2))^\frac{-1}{N+1}}}-1\bigg)e^\frac{\|c\|_{2(N+1)}^{2(N+1)}}{(N+1)(2N+1)}\\
& &\quad\leq \frac{Q_{d,\ell} (t)e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}}}{\mathrm{SINC}(\pi t)}-e^\frac{\|c\|_{2(N+1)}^{2(N+1)}}{(N+1)(2N+1)}\nonumber\\
& &\quad\leq e^\frac{d A^{2(N+1)}}{(N+1)(2N+1)} \Big(e^{O\bigg( \frac{1}{(\ell+1/2)^\frac{1}{N+1}}\bigg)}-1 \Big).\nonumber
\end{eqnarray}
The left most side of inequality (\ref{blork5}) is of the order $O((\ell+1/2)^{-\frac{N+2}{N+1}})$, and the right most side of inequality (\ref{blork5}) is of the order $O((\ell+1/2)^{-\frac{1}{N+1}})$, where the ``big O'' constants are independent of $c\in [-A,A]^d$.  The lemma follows readily.

Equivalently, we need to show $$\lim_{\ell \rightarrow \infty} \sup_{c \in [-A,A]^d} \Big| \Big(e^\frac{\| c\|_{2(N+1)}^{2(N+1)}}{(N+1)(2N+1)}  -1 \Big)f\big(c (\ell+1/2)^\frac{2N+1}{2N+2}\big) \Big| = 0.$$  Suppose the contrary.  Let $c_\ell \in [-A,A]^d$ be a value that maximizes the $\ell$-th term in the above limit.  There exists $(\ell_k)_{k \in \mathbb{N}}$, and $\epsilon>0$ such that for all $k \in \mathbb{N}$,
\begin{eqnarray}
\epsilon  &\leq&  \sup_{c \in [-A,A]^d} \Big| \Big(e^\frac{\| c\|_{2(N+1)}^{2(N+1)}}{(N+1)(2N+1)}  -1 \Big)f\big(c (\ell_k+1/2)^\frac{2N+1}{2N+2}\big) \Big|\nonumber\\ &\leq& \Big(e^\frac{d A^{2(N+1)}}{(N+1)(2N+1)}-1\Big)\big| f\big(c_{\ell_k}(\ell_k+1/2)^\frac{2N+1}{2N+2}\big) \big|,\nonumber
\end{eqnarray}
so that the sequence $\big( f\big(c_{\ell_k} (\ell_k+1/2)^\frac{2N+1}{2N+2}\big) \big)_{k \in \mathbb{N}}$ is bounded away from $0$.  This implies there exists $\delta >0$ such that $\big\| c_{\ell_k} (\ell_k+1/2)^\frac{2N+1}{2N+2} \big\|_{2(N+1)} \leq \delta$ for $k \in \mathbb{N}$, that is, $\| c_{\ell_k} \|_{2(N+1)} \leq \delta (\ell_k+1/2)^{-\frac{2N+1}{2N+2}}$.  This forces
\begin{eqnarray}
\epsilon &\leq&  \sup_{c \in [-A,A]^d} \Big| \Big(e^\frac{\| c\|_{2(N+1)}^{2(N+1)}}{(N+1)(2N+1)}  -1 \Big)f\big(c (\ell_k+1/2)^\frac{2N+1}{2N+2}\big) \Big|\nonumber\\  &\leq & \Big(e^\frac{\delta^{2(N+1)}}{(\ell_k+1/2)^{2N+1}(N+1)(2N+1)} -1 \Big)\| f \|_\infty.\nonumber
\end{eqnarray}
The last term in the above inequality has limit $0$ as $\ell \rightarrow \infty$, which is a contradiction.

If $f \in PW_{[-\pi,\pi]^d}$, Theorem \ref{maintheorem} states that $$f(t) = \frac{\Psi_\ell(t)}{Q_{d,\ell} (t)}\mathrm{SINC(\pi t)} +\xi_\ell (t)$$ where $\xi_\ell \rightarrow 0$ on $\mathbb{R}^d$ both in $L_2$ and $L_\infty$ senses.  By Lemma \ref{techlem1}, we have
\begin{eqnarray}\label{firstpart}
& &\sup_{t \in (E_{\ell,N,A})^d} \Big| \Psi_\ell(t)  e^{-\sum_{k=1}^{N} \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} - e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)} \frac{\Psi_\ell(t)}{Q_{d,\ell} (t)}\mathrm{SINC(\pi t)} \Big|\\
& &\quad\quad\leq M (\ell+1/2)^{-\frac{1}{N+1}}\sup_{t \in (E_{\ell,N,A})^d}(|f(t)| - |\xi_\ell(t)|),\nonumber
\end{eqnarray}
the right side of which has zero limit.  Also,
\begin{eqnarray}\label{secondpart}
& &\sup_{t \in (E_{\ell,N,A})^d}\quad\Big| \Big(e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}  -1 \Big) \frac{\Psi_\ell(t)}{Q_{d,\ell} (t)}\mathrm{SINC(\pi t)} \Big|\\
& &\quad \leq \sup_{t \in (E_{\ell,N,A})^d} \Big| \Big(e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}  -1 \Big)f(t) \Big|+\nonumber\\
& & \quad\quad\Big(e^\frac{d A^{2(N+1)}}{(N+1)(2N+1)} -1 \Big) \sup_{t \in (E_{\ell,N,A})^d} |\xi_\ell(t) |,\nonumber
\end{eqnarray}
whose right hand side, by Lemma \ref{techlem2}, also has zero limit.  Combining inequalities (\ref{firstpart}) and (\ref{secondpart}), we obtain
\begin{equation}
\lim_{\ell \rightarrow \infty} \Big\|  \Psi_\ell(t)  e^{-\sum_{k=1}^{N} \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} - \frac{\Psi_\ell(t)}{Q_{d,\ell} (t)}\mathrm{SINC(\pi t)} \Big\|_{L_\infty((E_{\ell,N,A})^d)}=0.\nonumber
\end{equation}
Equation (\ref{simplecor1}) follows by a final application of Theorem \ref{maintheorem}.\\

\noindent Now we prove equation (\ref{simplecor2}).  Lemma \ref{techlem1} and Theorem \ref{maintheorem} imply
\begin{eqnarray}\label{firstpartl2}
 & &\Big\| \Psi_\ell(t)  e^{-\sum_{k=1}^{N} \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} - e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)} \frac{\Psi_\ell(t)}{Q_{d,\ell} (t)}\mathrm{SINC(\pi t)} \Big\|_{L_2((E_{\ell,N,A})^d)}\\
& &\quad\leq M (\ell+1/2)^{-\frac{1}{N+1}} \|f + \xi_\ell\|_{L_2((E_{\ell,N,A})^d)},\nonumber
\end{eqnarray}
the right hand side of which has zero limit.  Also,
\begin{eqnarray}\label{secondpartl2}
& &\Big\| \Big(e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}  -1 \Big) \frac{\Psi_\ell(t)}{Q_{d,\ell} (t)}\mathrm{SINC(\pi t)} \Big\|_{L_2((E_{\ell,N,A})^d)}\\
& &\quad\leq \Big\| \Big(e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}  -1 \Big)f(t) \Big\|_{L_2((E_{\ell,N,A})^d)}+\nonumber\\
& & \quad\quad\Big\| \Big(e^\frac{\| t\|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}  -1 \Big)\xi_\ell(t) \Big\|_{L_2((E_{\ell,N,A})^d)}.\nonumber
\end{eqnarray}
The second term in the right hand side of inequality (\ref{secondpartl2}) is bounded from above by $$\Big(e^\frac{d A^{2(N+1)}}{(N+1)(2N+1)} -1 \Big) \|\xi_\ell\|_{L_2((E_{\ell,N,A})^d)},$$ which has zero limit.  The integrand of the first term in the right hand side of inequality (\ref{secondpartl2}) (as a function over $\mathbb{R}^d$), converges uniformly to zero by Lemma \ref{techlem2}, and is bounded from above by $$\Big(e^\frac{d A^{2(N+1)}}{(N+1)(2N+1)} -1 \Big) |f(t)|^2 \in L_1(\mathbb{R}^d),$$ so this term has zero limit by the Dominated Convergence Theorem. Combining equations (\ref{firstpartl2}) and (\ref{secondpartl2}) yields
\begin{equation}
\lim_{\ell \rightarrow \infty} \Big\|  \Psi_\ell(t)  e^{-\sum_{k=1}^{N} \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} - \frac{\Psi_\ell(t)}{Q_{d,\ell} (t)}\mathrm{SINC(\pi t)} \Big\|_{L_2((E_{\ell,N,A})^d)}=0.\nonumber
\end{equation}
Equation (\ref{simplecor2}) follows by a final application of Theorem \ref{maintheorem}.

\label{kadeclike}
Let $(t_k)_{k \in \mathbb{Z}^d} \subset \mathbb{R}^d$ such that
\begin{equation}
\sup_{n \in \mathbb{Z}^d} \Arrowvert n - t_n \Arrowvert_\infty = L < \frac{\ln(2)}{\pi d},\nonumber
\end{equation}
then the sequence $(f_k)_{k \in \mathbb{Z}^d}$ defined by $f_k (x) = \frac{1}{(2\pi)^{d/2}}e^{i \langle x , t_k \rangle}$ is a Riesz basis for $L_2([-\pi,\pi]^d)$.

\label{sunzhou}
For $d \geq 1$, define $$D_d(x) := \Big(1-\cos \pi x+\sin \pi x  +\frac{\sin \pi x}{\pi x} \Big)^d -\Big( \frac{\sin \pi x}{\pi x} \Big)^d,$$ and let $x_d$ be the unique number such that $0 < x_d \leq 1/4$ and $D_d(x_d)=1$.  Let $(t_k)_{k \in \mathbb{Z}^d} \subset \mathbb{R}^d$ such that  
\begin{equation}
\sup_{n \in \mathbb{Z}^d} \| n - t_n \|_\infty< x_d,\nonumber
\end{equation}
then the sequence $(f_k)_{k \in \mathbb{Z}^d}$  defined by $f_k (x) = \frac{1}{(2\pi)^{d/2}}e^{i \langle x , t_k \rangle}$ is a Riesz basis for $L_2([-\pi,\pi]^d)$.

\label{normpert}
Let $L: H \rightarrow H$ be a uniformly invertible operator with respect to $(P_\ell)_{\ell \in \mathbb{N}}$, where $$\limsup_{\ell \rightarrow \infty}\| (P_\ell L P_\ell)^{-1} \| = M <\infty.$$  If $A$ is an operator such that
\begin{equation}\label{neumann}
\| L- A \| =\frac{\gamma}{M}
\end{equation}
for some $\gamma <1$, then there exists $N \in \mathbb{N}$ such that $A$ is uniformly invertible with respect to $(P_\ell)_{\ell \geq N}$.

From the definition of $L_\ell$, we have $I = (I-P_\ell)L_\ell^{-1}+L P_\ell L_\ell^{-1}$, so that $$L^{-1}(P_\ell-I)L_\ell^{-1} = P_\ell L_\ell^{-1} -L^{-1}.$$  This implies 
\begin{equation}\label{thisone}
(L_\ell^*)^{-1}P_\ell -(L^*)^{-1} = (L_\ell^*)^{-1}(P_\ell -I)(L^*)^{-1}.
\end{equation}
As $\ell \rightarrow \infty$, the right hand side of equation (\ref{thisone}) has 0 limit pointwise.  Combined with the compactness of $\Delta$, we obtain $$\lim_{\ell \rightarrow \infty} (L_\ell^*)^{-1}P_\ell \Delta = (L^*)^{-1} \Delta$$ where limit is in the operator norm topology.  This yields
\begin{equation}\label{thatone}
\lim_{\ell \rightarrow \infty} I+\Delta P_\ell L_\ell^{-1} = I+\Delta L^{-1} = (L+\Delta)L^{-1},
\end{equation}
where the limit is also in the operator norm topology.  The right had side of equation (\ref{thatone}) is invertible, so there exists $N$ such that $\ell \geq N$ implies $(I+\Delta P_\ell L_\ell^{-1})^{-1}$ exists, and 
\begin{equation}\label{newsup}
\sup_{\ell \geq N} \| (I+\Delta P_\ell L_\ell^{-1})^{-1} \| < \infty.
\end{equation}
From the definition of $\tilde{L}_\ell$, we obtain
\begin{eqnarray}
\tilde{L}_\ell = L_\ell +\Delta P_\ell = (I+\Delta P_\ell L_\ell^{-1})L_\ell.\nonumber
\end{eqnarray}
When $\ell \geq N$, we have $$\tilde{L}_\ell^{-1} = L_\ell^{-1} (I+\Delta P_\ell L_\ell^{-1})^{-1},$$ and equation (\ref{newsup}) implies
\begin{equation}
\sup_{\ell \geq N} \|\tilde{L}_\ell^{-1} \| \leq \sup_{\ell \geq N} \| L_\ell^{-1} \| \sup_{\ell \geq N} \| (I+\Delta P_\ell L_\ell^{-1})^{-1} \| < \infty.
\end{equation}
This completes the proof.

\label{mainlemma}
Choose $(t_k)_{k \in \mathbb{N}} \subset \mathbb{R}^d$ such that $(h_k)_{k \in \mathbb{N}} :=  \big(\frac{1}{(2\pi)^{d/2}}e^{i\langle (\cdot) , t_k \rangle}\big)_{k \in \mathbb{N}}$ satisfies $$\Big\| \sum_{k=1}^n a_k h_k \Big\|_{L_2 [-\pi,\pi]^d} \leq B \Big(\sum_{k=1}^n |a_k|^2 \Big)^{1/2}, \quad \mathrm{for \ all} \quad (c_k)_{k=1}^n \subset \mathbb{C}.$$  If $(\tau_k)_{k \in \mathbb{N}} \subset \mathbb{R}^d$, and $(f_k)_{k \in \mathbb{N}} := \big(\frac{1}{(2\pi)^{d/2}} e^{i \langle (\cdot) , \tau_k \rangle}\big)_{k \in \mathbb{N}}$, then for all $r,s\geq 1$ and any finite sequence $(a_k)_k$, we have
\begin{equation}             
\Bigg\Arrowvert \sum_{k=r}^s a_k ( h_k - f_k ) \Bigg\Arrowvert_{L_2 [-\pi,\pi]^d} \\
{} \leq B\Big( e^{\pi d \big({\sup \atop {r \leq k \leq s}} \Arrowvert \tau_k-t_k \Arrowvert_\infty\big)}-1 \Big) \Big(\sum_{k=r}^s |a_k|^2\Big)^\frac{1}{2}.\nonumber
\end{equation}

\label{rbreplace}
Let $(f_n)_{n \in \mathbb{Z}}$ be an exponential Riesz basis for $L_2[-\pi,\pi]$.  If $(g_n)_{|n| \leq \ell}$ is a sequence of complex exponentials such that
\begin{equation}
(g_n)_{|n| \leq \ell} \cup (f_n)_{|n|>{\ell_0}}\nonumber
\end{equation}
consists of distinct functions, then this set is a Riesz basis for $L_2[-\pi,\pi]$.

\noindent Define $L e_n = f_n$ and $\tilde{L}e_n = g_n$.  By Corollary \ref{compactcor}, $\tilde{L}$ is bounded linear and $\tilde{L} = L+\Delta$ for some compact operator $\Delta$.  Define the operator \begin{displaymath}
   R_\ell e_n = \left\{
     \begin{array}{lr}
       f_n,  &  |n| \leq \ell\\
       g_n & |n| > \ell
     \end{array}
   \right..
\end{displaymath}
Rewritten, we have
\begin{equation}
R_\ell = L P_\ell +(L+\Delta)(I-P_\ell) = L+\Delta(I-P_\ell).\nonumber
\end{equation}
Compactness of $\Delta$ implies that $\lim_{\ell \rightarrow \infty} R_\ell = L$ in the operator norm topology.  We conclude that $R_{\ell_0}$ is an onto isomorphism for some $\ell_0$ sufficently large; that is, the set 
\begin{equation}\label{dumb}
(f_n)_{|n| \leq \ell_0} \cup (g_n)_{|n|>{\ell_0}}
\end{equation}
is a Riesz basis for $L_2[-\pi,\pi]$.  If we apply Lemma \ref{rbreplace}, by replacing $(f_n)_{|n| \leq \ell_0}$ with $(g_n)_{|n| \leq \ell_0}$ in expression (\ref{dumb}), we have that $(g_n)_{n \in \mathbb{Z}}$ is a Riesz basis for $L_2[-\pi,\pi].$

\label{sinctheorem}
Define 
\begin{eqnarray}
C_{\ell,N} & = & \Big(\frac{1}{4}(2N+1)^2 (\ell+1/2)^{2N+1} \log(\ell+1/2)\Big)^\frac{1}{2(N+1)}, \ \mathrm{and}\nonumber\\
D_{\ell,N} & = & \Big(\frac{1}{2}(2N+1)^2 (\ell+1/2)^{2N+1} \log(\ell+1/2)\Big)^\frac{1}{2(N+1)},\nonumber
\end{eqnarray}
then
\begin{equation}\label{sinctheorem1}
\lim_{\ell \rightarrow \infty} \Big\| \mathrm{SINC}(\pi t) - I_{\mathrm{SINC}\pi(\cdot), \ell}(t)  \Big\|_{L_2([-C_{\ell,N},C_{\ell,N}]^d)}=0,
\end{equation}
and
\begin{equation}\label{sinctheorem2}
\lim_{\ell \rightarrow \infty} \Big\| \mathrm{SINC}(\pi t) - I_{\mathrm{SINC}\pi(\cdot), \ell}(t)  \Big\|_{L_\infty([-D_{\ell,N},D_{\ell,N}]^d)}=0.
\end{equation}

\label{auxprop1}
\begin{equation}\label{firstbit}
\lim_{\ell \rightarrow \infty} \Big\|\Big( e^{ \frac{\| t \|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}}-1\Big) \mathrm{SINC}(\pi t) \Big\|_{L_2([-C_{\ell,N},C_{\ell,N}]^d)} = 0.
\end{equation}

\label{auxprop2}
\begin{eqnarray}
\lim_{\ell \rightarrow \infty} \Big\| Q_{d,\ell}(t) e^{-\!\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}}\!\!-\!e^{ \frac{\| t \|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}}\mathrm{SINC}(\pi t)  \Big\|_{L_2([-C_{\ell,N},C_{\ell,N}]^d)}\!=\!0.\nonumber
\end{eqnarray}

If $t \in \mathbb{R}^d$ and $\|t \|_\infty <\ell+1/2$, then equation (\ref{blork3}) implies
\begin{eqnarray}\label{needsone}
& & \bigg(e^{\sum_{k=N+1}^\infty \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} \bigg)\prod_{k=1}^d e^{\bigg(-\frac{1}{2(\ell+1/2)}\frac{\big( \frac{t}{\ell+1/2} \big)^2}{1-\big(\frac{t}{\ell+1/2} \big)^2}\bigg)}\\
& &\quad \leq\frac{Q_{d,\ell} (t)e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}}}{\mathrm{SINC}(\pi t)} \leq  e^{\sum_{k=N+1}^\infty \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}}.\nonumber
\end{eqnarray}
Let $t \in [-C_{\ell,N},C_{\ell,N}]^d$ where $t= \alpha C_{\ell,N}$, $\alpha \in [-1,1]$.  Consider the right hand side of inequality (\ref{needsone}) for such $t$.
\begin{eqnarray}
& & e^{\sum_{k=N+1}^\infty \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} \leq \Big( \ell+\frac{1}{2} \Big)^{\frac{2N+1}{4(N+1)}\|\alpha \|_{2(N+1)}^{2(N+1)}} e^{(\ell+1/2) O \Big( \big\| \frac{t}{\ell+1/2} \big\|_{2(N+2)}^{2(N+2)} \Big)}\\
& &\quad\leq \Big( \ell+\frac{1}{2} \Big)^{\frac{2N+1}{4(N+1)}\|\alpha \|_{2(N+1)}^{2(N+1)}} e^{M (\ell+1/2)^{-\frac{1}{N+1}} (\log(\ell+1/2) )^\frac{N+2}{N+1} \| \alpha \|_{2(N+2)}^{2(N+2)} }.\nonumber
\end{eqnarray}
for some constant $M$. Noting that $$ \frac{t^2}{(\ell+1/2)^3} = \frac{\| \alpha \|_2^2 \big(\frac{1}{4}(2N+1)^2\big)^\frac{1}{N+1}\big( \log(\ell+1/2)\big)^\frac{1}{N+1}}{(\ell+1/2)^\frac{N+2}{N+1}},$$ we can bound the left hand side of inequality (\ref{needsone}) from below as follows:
\begin{eqnarray}\label{blahblah}
& & e^{\Big(-m  \frac{\| \alpha \|_2^2 \big( \log(\ell+1/2)\big)^\frac{1}{N+1}}{(\ell+1/2)^\frac{N+2}{N+1}} \Big)} \Big( \ell+\frac{1}{2} \Big)^{\frac{2N+1}{4(N+1)}\|\alpha \|_{2(N+1)}^{2(N+1)}}\\
& &\quad\leq \bigg(e^{\sum_{k=N+1}^\infty \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} \bigg)\prod_{k=1}^d e^{\bigg(-\frac{1}{2(\ell+1/2)}\frac{\big( \frac{t}{\ell+1/2} \big)^2}{1-\big(\frac{t}{\ell+1/2} \big)^2}\bigg)},\nonumber
\end{eqnarray}
where $m>0$ is chosen independently of $\ell$.  Relations (\ref{needsone}) through (\ref{blahblah}) imply
\begin{eqnarray}
& & \bigg( e^{\Big(-m  \frac{(\log(\ell+1/2))^\frac{1}{N+1}\| \alpha \|_2^2}{(\ell+1/2)^\frac{N+2}{N+1}} \Big)}-1\bigg) \Big( \ell+\frac{1}{2} \Big)^{\frac{2N+1}{4(N+1)}\|\alpha \|_{2(N+1)}^{2(N+1)}} |\mathrm{SINC}(\pi t)| \nonumber\\
& &\quad\leq \bigg| Q_{d,\ell}(t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}}-e^{ \frac{\| t \|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}}\mathrm{SINC}(\pi t)  \bigg| \nonumber\\
& &\quad\leq \bigg( e^{\Big(M \frac{ (\log(\ell+1/2) )^\frac{N+2}{N+1} \| \alpha \|_{2(N+2)}^{2(N+2)}}{(\ell+1/2)^\frac{1}{N+1}}\Big)}-1 \bigg) \Big( \ell+\frac{1}{2} \Big)^{\frac{2N+1}{4(N+1)}\|\alpha \|_{2(N+1)}^{2(N+1)}}|\mathrm{SINC}(\pi t)|.\nonumber
\end{eqnarray}
Further simplification implies (for appropriate constants $C$, $C'$, and $C''$) that
\begin{eqnarray}
& & \Big\| Q_{d,\ell}(t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}}-e^{ \frac{\| t \|_{2(N+1)}^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}}\mathrm{SINC}(\pi t)  \Big\|_{L_2([-C_{\ell,N},C_{\ell,N}]^d)} \nonumber\\
& &\quad\leq C\frac{(\log(\ell+1/2))^\frac{N+2}{N+1}}{(\ell+1/2)^\frac{1}{N+1}} \Bigg(\int_{[-C_{\ell,N},C_{\ell,N}]^d} \Bigg| \Big( \ell+\frac{1}{2} \Big)^{\frac{2N+1}{4(N+1)}\|\alpha \|_{2(N+1)}^{2(N+1)}} \| \alpha \|_2^2 \mathrm{SINC}(\pi t)  \Bigg|^2  dt \Bigg)^{1/2}\nonumber\\
& &\quad =C'\frac{(\log(\ell+1/2))^\frac{N+2}{N+1}}{(\ell+1/2)^\frac{1}{N+1}} \Bigg(\int_{[-1,1]^d} \frac{\Bigg| \Big( \ell+\frac{1}{2} \Big)^{\frac{2N+1}{4(N+1)}\|\alpha \|_{2(N+1)}^{2(N+1)}} \| \alpha \|_2^2 \mathrm{SINC}(\pi t)  \Bigg|^2}{(\log(\ell+1/2))^\frac{d}{2(N+1)}\big(\ell+\frac{1}{2} \big)^{\frac{2N+1}{2(N+1)}d}}  d\alpha \Bigg)^{1/2}\nonumber\\
& &\quad\leq  C''\frac{(\log(\ell+1/2))^\frac{N+2}{N+1}}{(\ell+1/2)^\frac{1}{N+1} (\log(\ell+1/2))^\frac{d}{4(N+1)}},\nonumber
\end{eqnarray}
after the change in variable $t = \alpha C_{\ell,N}$ and simple estimates.  This proves the proposition.

\label{auxprop3}
\begin{equation}\label{thirdbit}
\lim_{\ell \rightarrow \infty} \Big\|\Big( e^{ \frac{ t^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}}-1\Big) \mathrm{sinc}(\pi t) \Big\|_{L_\infty [-D_{\ell,N},D_{\ell,N}]} = 0.
\end{equation}

Let $t \in [-D_{\ell,N},D_{\ell,N}]$, then $t = \alpha D_{\ell,N}$ for $\alpha \in [-1,1]$. Simplification shows that equation (\ref{thirdbit}) holds if
\begin{equation}\label{sam}
\lim_{\ell \rightarrow \infty} \sup_{\alpha \in [0,1]} \bigg| \frac{(\ell+1/2)^{\alpha^{2(N+1)}\frac{2N+1}{2(N+1)}}-1}{\alpha \big(\log(\ell+1/2)\big)^\frac{1}{2(N+1)} (\ell+1/2)^\frac{2N+1}{2(N+1)}} \bigg| = 0.
\end{equation}
Note that for large $\ell$,
\begin{equation}\label{sam2}
\sup_{\alpha \in [1/2,1]} \Bigg| \frac{(\ell+1/2)^{\alpha^{2(N+1)}\frac{2N+1}{2(N+1)}}-1}{\alpha \big(\log(\ell+1/2)\big)^\frac{1}{2(N+1)} (\ell+1/2)^\frac{2N+1}{2(N+1)}} \Bigg| \leq \frac{2}{\big(\log(\ell+1/2)\big)^\frac{1}{2(N+1)}}.
\end{equation}
\noindent Let $0  < \alpha \leq 1/2$.  The Mean Value Theorem implies
\begin{equation}
\bigg| \frac{(\ell+1/2)^{\alpha^{2(N+1)}\frac{2N+1}{2(N+1)}}-1}{\alpha} \bigg| \leq (2N+1)(\ell+1/2)^{\alpha^{2(N+1)}\frac{2N+1}{2(N+1)}} \alpha^{2N+1} \log(\ell+1/2).
\end{equation}
This yields
\begin{eqnarray}
\sup_{\alpha \in [0,1/2]} \bigg| \frac{(\ell+1/2)^{\alpha^{2(N+1)}\frac{2N+1}{2(N+1)}}-1}{\alpha \big(\log(\ell+1/2)\big)^\frac{1}{2(N+1)} (\ell+1/2)^\frac{2N+1}{2(N+1)}} \bigg|\leq M \frac{\big(\log(\ell+1/2)\big)^\frac{2N+1}{2(N+1)}}{(\ell+1/2)^{\frac{2N+1}{2(N+1)}(1-(1/2)^{2(N+1)})}}\nonumber
\end{eqnarray}
for some constant $M$. Combined with inequality (\ref{sam2}), we have equation (\ref{sam}), which proves the proposition.

\label{blip6}
\begin{equation}\label{fourthbit}
\lim_{\ell \rightarrow \infty} \Big\| Q_{1,\ell}(t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}}-e^{ \frac{t^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1)}}\mathrm{sinc}(\pi t)  \Big\|_{L_\infty [-D_{\ell,N},D_{\ell,N}]}=0.\nonumber
\end{equation}

\label{l2bound}
Let $N \geq 0$.  If $(M_{\ell,N})_\ell$ is a sequence of positive numbers such that (\ref{sinctheorem1}) holds when $(C_{\ell,N})_\ell$ is replaced by $(M_{\ell,N})_\ell$, then
\begin{equation}\label{l2boundeq}
\limsup_{\ell \rightarrow \infty} \frac{M_{\ell,N}}{C_{\ell,N}} \leq 1.
\end{equation}

Fix $N\geq0$, and define $c=\frac{2N+1}{2N+4}+\delta/2$ where $0<\delta$ is small enough so that $c<1/2$.  Define $$A_\ell = (c(N+1)(2N+1)\log(\ell+1/2))^\frac{1}{2(N+1)}(\ell+1/2)^\frac{-1}{2(N+1)}$$ and $$\epsilon_\ell = (\ell+1/2)^{1-2c} A_\ell.$$  Note that $\lim_{\ell \rightarrow \infty} \epsilon_\ell = 0.$  Let $t \in [A_\ell (\ell+1/2), (1+\epsilon_\ell)A_\ell(\ell+1/2)],$ then $t=\alpha(\ell +1/2)$ for some $\alpha \in [A_\ell,(1+\epsilon_\ell)A_\ell]$. For large $\ell$, note that inequality (\ref{blork3}) implies
\begin{eqnarray}
\frac{1}{2\pi}e^\frac{(\ell+1/2)\alpha^{2(N+1)}}{(N+1)(2N+1)}\frac{|\sin \pi\alpha(\ell+1/2)|}{\alpha (\ell+1/2)} \leq \Big| Q_{1,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}} \Big|.
\end{eqnarray}
Moving to the multivariate case, if $t \in [A_\ell (\ell+1/2), (1+\epsilon_\ell)A_\ell(\ell+1/2)]^d$, then $t = \alpha (\ell+1/2)$ for some $\alpha \in [A_\ell, (1+\epsilon_\ell)A_\ell]^d$.  This yields




\begin{eqnarray}
\prod_{i=1}^d \frac{1}{2\pi\alpha_i^c} \frac{|\sin \pi\alpha_i(\ell+1/2)|}{(\alpha_i(\ell+1/2))^{1-c}} \leq  \Big| Q_{d,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} \Big|.\nonumber
\end{eqnarray}
For sufficiently large $\ell$, we can conclude
\begin{eqnarray}
& &\bigg[\frac{1}{9 \pi^2 A_\ell^{2c}} \int_{A_\ell(\ell+1/2)}^{(1+\epsilon_\ell)A_\ell(\ell+1/2)} \frac{\sin^2 \pi x}{x^{2-2c}}dx\bigg]^d\nonumber\\
& &\quad\leq \int_{[A_\ell(\ell+1/2),(1+\epsilon_\ell)A_\ell(\ell+1/2)]^d}  \Big| Q_{d,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} \Big|^2 dt.\nonumber
\end{eqnarray}

\noindent Applying Proposition \ref{blork6} for $a= A_\ell (\ell+1/2)$, $\epsilon = \epsilon_\ell,$ and $\omega = 1-2c$, and using the definition of $\epsilon_\ell$, we obtain
\begin{eqnarray}
& &\bigg[\frac{1}{9\pi^2}\Big[\frac{1}{2(1+\epsilon_\ell)^{1-2c}} - \frac{1}{2 A_\ell^{2c}(A_\ell(\ell+1/2)-1)^{2-2c}} \Big]\bigg]^d\nonumber\\
& &\quad\leq \int_{[A_\ell(\ell+1/2),(1+\epsilon_\ell)A_\ell(\ell+1/2)]^d}  \Big| Q_{d,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} \Big|^2 dt.\nonumber
\end{eqnarray}
The first term in the brackets in the previous equation has limit $1/2$, while the second term has limit $0$. We conclude there exists a constant $\beta >0$ such that
\begin{equation}\label{blork7}
\beta \leq \int_{[A_\ell(\ell+1/2),(1+\epsilon_\ell)A_\ell(\ell+1/2)]^d}  \Big| Q_{d,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} \Big|^2 dt, \quad \ell >0.
\end{equation}
If $M_{\ell,N} \geq (\ell+1/2)(1+\epsilon_\ell)A_\ell$ for infinitely many $\ell$, there exists a subsequence $(\ell_k)_{k \in \mathbb{N}}$ such that (in particular),
\begin{eqnarray}
\lim_{\ell_k \rightarrow \infty}\! \Big\| \mathrm{SINC}(\pi t) - Q_{d,\ell_k}(t) e^{-\sum_{k=1}^{N} \frac{1}{k(2k-1)}\frac{\| t \|_{2k}^{2k}}{(\ell_k+1/2)^{2k-1}}}\Big\|_{L_2([A_{\ell_k} (\ell_k+1/2)), A_{\ell_k} (\ell_k+1/2)(1+\epsilon_{\ell_k})]^d)}\!\!=\!0.\nonumber
\end{eqnarray}
This contradicts inequality (\ref{blork7}).  This yields that for sufficiently large $\ell$, 
\begin{eqnarray}
 M_{\ell,N} &<& (\ell+1/2)(1+\epsilon_\ell)A_\ell\nonumber\\
& = & (1+\epsilon_\ell)\Big(\Big(\frac{2N+1}{4N+4}+\delta/2 \Big)(N+1)(2N+1)(\ell+1/2)^{2N+1}\log(\ell+1/2)\Big)^\frac{1}{2(N+1)}.\nonumber
\end{eqnarray}
Note that since $\epsilon_\ell \rightarrow 0$, for large $\ell$, the quantity $(1+\epsilon_\ell)\Big(\frac{2N+1}{4N+4}+\delta/2 \Big)^\frac{1}{2(N+1)}$ is less than, (and bounded away from) the quantity $\Big(\frac{2N+1}{4N+4}+\delta \Big)^\frac{1}{2(N+1)}$.  We conclude that for any $\delta>0$, there exists $\ell_{N,\delta}$ such that $$ \sup_{\ell >\ell_{N,\delta}} \frac{M_{\ell,N}}{((N+1)(2N+1)\log(\ell+1/2))^\frac{1}{2(N+1)}(\ell+1/2)^\frac{2N+1}{2(N+1)}} < \Big( \frac{2N+1}{4N+4} +\delta \Big)^\frac{1}{2(N+1)}.$$  Proposition \ref{l2bound} follows.

\label{linfbound}
Let $N \geq 0$.  If $(M_{\ell,N})_\ell$ is a sequence of positive numbers such that equation (\ref{sinctheorem2}) holds when $(D_{\ell,N})_\ell$ is replaced by $(M_{\ell,N})_\ell$, then
\begin{equation}
\limsup_{\ell \rightarrow \infty} \frac{M_{\ell,N}}{D_{\ell,N}} \leq 1.
\end{equation}

Let $N \geq 0$. Choose $\delta>0$ such that $c := \frac{2N+1}{2N+2}+\delta/2<1$. Define $$A_\ell = (c(N+1)(2N+1)\log(\ell+1/2))^\frac{1}{2(N+1)}(\ell+1/2)^\frac{-1}{2(N+1)}$$ and $$\epsilon_\ell = A_\ell (\ell+1/2)^{1-c}.$$ Note that $\lim_{\ell \rightarrow \infty} \epsilon_\ell = 0$.  Let $t \in [A_\ell (\ell+1/2),A_\ell(\ell+1/2)+\epsilon_\ell].$ Proceeding as before, for sufficiently large $\ell$, we have
\begin{equation}
\frac{1}{2\pi}e^{\Big(\frac{t^{2(N+1)}}{(\ell+1/2)^{2N+1}(N+1)(2N+1))}\Big)} \frac{|\sin(\pi t)|}{t} \leq \Big| Q_{1,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}}\Big|.\nonumber
\end{equation}
Now for all $t \in [A_\ell (\ell+1/2),A_\ell(\ell+1/2)+\epsilon_\ell]$,\\
\begin{equation}
\frac{1}{2\pi}\frac{(\ell+1/2)^c}{A_\ell(\ell+1/2)+\epsilon_\ell}|\sin(\pi t)| \leq \Big| Q_{1,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{t^{2k}}{(\ell+1/2)^{2k-1}}}\Big|.\nonumber
\end{equation}
In the multivariate case, if $t \in [A_\ell (\ell+1/2),A_\ell(\ell+1/2)+\epsilon_\ell]^d$, we obtain
\begin{equation}
 \frac{1}{(2\pi)^d}\frac{(\ell+1/2)^{cd}}{(A_\ell(\ell+1/2)+\epsilon_\ell)^d}\prod_{i=1}^d |\sin(\pi t_i)| \leq \Big| Q_{d,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}}\Big|.\nonumber
\end{equation}
For large $\ell$, an application of Proposition \ref{sinprop} yields
\begin{equation}
\frac{1}{(3\pi)^d}\frac{|\sin(\pi \epsilon_\ell/2)|^d}{A_\ell^d(\ell+1/2)^{(1-c)d}} \leq \Big\| Q_{d,\ell} (t) e^{-\sum_{k=1}^N \frac{1}{k(2k-1)}\frac{\|t\|_{2k}^{2k}}{(\ell+1/2)^{2k-1}}} \Big\|_{L_\infty([A_\ell (\ell+1/2),A_\ell(\ell+1/2)+\epsilon_\ell]^d)}.\nonumber
\end{equation}
By the definition of $\epsilon_\ell$, the right hand side of the above equation tends to a positive constant.  The remainder of the proof is almost identical to that of Proposition \ref{l2bound}.
